import org.openenglish.reader.*;import android.content.*;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class MagicBackupTest {
 static int checks;static void check(boolean v,String s){if(!v)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}static void rejects(JSONObject j,String s)throws Exception{boolean failed=false;try{MagicBackup.validate(j);}catch(Exception e){failed=true;}check(failed,s);}
 static JSONObject clone(JSONObject j){return new JSONObject(j.toString());}
 public static void main(String[] args)throws Exception{
  File root=Files.createTempDirectory("backup-magic-").toFile();Context c=new Context(root,root);SharedPreferences p=c.getSharedPreferences("language_magic",0);p.edit().putString("lang","yue").putString("last_lesson","yue_si3").putInt("stars",9).putFloat("middle_hz",180.5f).putStringSet("favorites",new HashSet<>(Arrays.asList("yue_si3"))).putStringSet("done_2026-10-11",new HashSet<>(Arrays.asList("yue_si3"))).putLong("scene_yue_茶餐厅",17).putString("last_scene_yue","茶餐厅").putString("api_key","excluded").commit();
  IslandMemory m=new IslandMemory(c,"yue");m.note("慢一点");m.complete("奶茶","少甜？","茶餐厅");new IslandReview(c).rate("yue_si3",0);float[] audio=new float[16000];for(int i=0;i<audio.length;i++)audio[i]=(float)Math.sin(i*.09)*.2f;LessonAudio.write(MagicBackup.take(c,"yue_si3"),audio);
  JSONObject data=MagicBackup.snapshot(c);check(!data.toString().contains("api_key")&&!data.toString().contains("excluded"),"secrets and unrelated preferences excluded");check(data.getJSONArray("takes").getString(0).equals("language-takes/yue_si3.wav"),"lesson recording linked");
  Map<String,PortableZip.Source> sources=new LinkedHashMap<>();sources.put("learning.json",()->new ByteArrayInputStream("{}".getBytes()));sources.put("settings.json",()->new ByteArrayInputStream("{}".getBytes()));sources.put("magic.json",()->new ByteArrayInputStream(data.toString().getBytes("UTF-8")));sources.put("language-takes/yue_si3.wav",()->new FileInputStream(MagicBackup.take(c,"yue_si3")));
  ByteArrayOutputStream out=new ByteArrayOutputStream();PortableZip.write(out,sources,()->{},(n,f,b)->{});String token="restored-media/00000000-0000-0000-0000-000000000001";File stage=new File(root,token);stage.mkdirs();Map<String,PortableZip.Receipt> receipts=PortableZip.read(new ByteArrayInputStream(out.toByteArray()),stage,()->{},(n,f,b)->{});check(receipts.containsKey("magic.json")&&LocalWav.read(new File(stage,"language-takes/yue_si3.wav")).length==16000,"magic JSON and WAV actual checksummed archive round trip");
  m.clear();p.edit().putInt("stars",99).commit();c.failCommit="island_review";boolean failed=false;try{MagicBackup.apply(c,data,token);}catch(IOException e){failed=true;}check(failed&&!token.equals(p.getString("_restore_applied","")),"failed commit never marks migration complete");MagicBackup.apply(c,data,token);
  check(m.count()==1&&m.note().equals("慢一点")&&p.getInt("stars",0)==9&&p.getFloat("middle_hz",0)==180.5f,"retry recovers typed state and complete memory");check(p.getStringSet("favorites",Collections.emptySet()).contains("yue_si3")&&p.getLong("scene_yue_茶餐厅",0)==17,"favorites and scene mapping preserved");check(new IslandReview(c).card("yue_si3").lapses==1,"review spacing restored");check(MagicBackup.take(c,"yue_si3").getCanonicalPath().startsWith(stage.getCanonicalPath()),"restored recording path switched only after apply");
  p.edit().putInt("stars",12).commit();MagicBackup.apply(c,data,token);check(p.getInt("stars",0)==12,"startup retry does not reset newer learning");JSONObject again=MagicBackup.snapshot(c);check(again.getJSONArray("takes").length()==1&&!again.toString().contains("_take_root"),"re-export includes relocated audio without device path");
  JSONObject bad=clone(data);bad.getJSONArray("takes").put("language-takes/../secret.wav");rejects(bad,"traversal path rejected before apply");bad=clone(data);bad.getJSONObject("preferences").getJSONObject("language_magic").getJSONObject("stars").put("type","string");rejects(bad,"numeric preference type mismatch rejected");bad=clone(data);bad.getJSONObject("preferences").getJSONObject("language_magic").getJSONObject("middle_hz").put("value",1);rejects(bad,"invalid calibration rejected");bad=clone(data);bad.getJSONObject("preferences").getJSONObject("language_magic").getJSONObject("stars").put("value",1.5);rejects(bad,"fractional integer rejected");bad=clone(data);bad.getJSONObject("preferences").getJSONObject("island_memory").getJSONObject("yue_pairs").put("value","[{}]");rejects(bad,"malformed completed pair rejected");bad=clone(data);bad.getJSONObject("preferences").getJSONObject("island_review").getJSONObject("yue_si3").put("value","{\"ease\":0}");rejects(bad,"malformed review card rejected");bad=clone(data);bad.put("version",2);rejects(bad,"future magic format rejected");
  check(!PortableZip.allowed("language-takes/../secret.wav")&&!PortableZip.allowed("language-takes/a.wav.part"),"archive allowlist blocks incomplete and external paths");check(!new File(root,"secret.wav").exists(),"invalid inputs leave files outside recording directory untouched");
  System.out.println("MAGIC_BACKUP_CHECKS: "+checks);
 }
}
